#!/usr/bin/env python3
"""A small terminal search/replace UI compatible with the observed executable.

This is an original reimplementation based on documented and observed behavior.
"""
from __future__ import annotations

import os
import sys
import re
import pwd
import tty
import time
import termios
import select
import shutil
import signal
from dataclasses import dataclass, field
from pathlib import Path
from typing import List, Optional, Tuple, Callable

HELP_TEXT = """A simple terminal UI for search and replace, ala VS Code

Usage: executable [OPTIONS]

Options:
  -p, --project-root <PATH>  Path to the project root [default: .]
  -h, --help                 Print help
  -V, --version              Print version"""

SEARCH_MODES = [
    "Simple",
    "Match Case",
    "Match Whole Word",
    "Match Case Whole Word",
    "Regex",
]
REPLACE_MODES = ["Simple", "Preserve Case", "Delete Line"]

# ANSI snippets matching the general style of the original.  Plain screen text is
# the important part; styles are intentionally modest.
RESET = "\x1b[0m"
FG_WHITE = "\x1b[38;5;15m"
FG_GREEN = "\x1b[38;5;2m"
FG_BLUE = "\x1b[38;5;4m"
FG_YELLOW = "\x1b[38;5;3m"
FG_GRAY = "\x1b[38;5;8m"
BG_BLUE = "\x1b[48;5;4m"
BOLD = "\x1b[1m"


def eprint(s: str) -> None:
    sys.stderr.write(s)
    sys.stderr.flush()


def config_dir() -> str:
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return os.path.join(xdg, "serpl")
    home = os.environ.get("HOME") or ""
    if not home:
        try:
            home = pwd.getpwuid(os.getuid()).pw_dir
        except Exception:
            home = os.path.expanduser("~")
    return os.path.join(home, ".config", "serpl")


def print_version() -> None:
    sys.stdout.write(
        f"serpl 0.3.4- (2026-04-20)\n\n"
        f"Authors: Yassine Bridi <ybridi@gmail.com>\n\n"
        f"Config directory: {config_dir()}\n"
    )


def arg_error(kind: str, arg: str = "") -> int:
    if kind == "missing":
        eprint("error: a value is required for '--project-root <PATH>' but none was supplied\n\n"
               "For more information, try '--help'.\n")
    elif kind == "duplicate":
        eprint("error: the argument '--project-root <PATH>' cannot be used multiple times\n\n"
               "Usage: executable [OPTIONS]\n\n"
               "For more information, try '--help'.\n")
    else:
        eprint(f"error: unexpected argument '{arg}' found\n\n"
               "Usage: executable [OPTIONS]\n\n"
               "For more information, try '--help'.\n")
    return 2


def parse_args(argv: List[str]) -> Tuple[Optional[str], Optional[int]]:
    """Return (project_root, exit_code_if_already_handled)."""
    project = "."
    seen_project = False
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            if i + 1 < len(argv):
                return project, arg_error("unexpected", argv[i + 1])
            return project, None
        if a in ("-h", "--help"):
            sys.stdout.write(HELP_TEXT + "\n")
            return project, 0
        if a in ("-V", "--version"):
            print_version()
            return project, 0
        if a == "--project-root" or a == "-p":
            if seen_project:
                return project, arg_error("duplicate")
            if i + 1 >= len(argv):
                return project, arg_error("missing")
            nxt = argv[i + 1]
            if nxt in ("-h", "--help", "-V", "--version"):
                return project, arg_error("missing")
            if nxt.startswith("-"):
                return project, arg_error("unexpected", nxt)
            project = nxt
            seen_project = True
            i += 2
            continue
        if a.startswith("--project-root="):
            if seen_project:
                return project, arg_error("duplicate")
            val = a.split("=", 1)[1]
            if val == "":
                return project, arg_error("missing")
            project = val
            seen_project = True
            i += 1
            continue
        if a.startswith("-p") and a != "-p":
            if seen_project:
                return project, arg_error("duplicate")
            val = a[2:]
            if val.startswith("="):
                val = val[1:]
            if val == "":
                return project, arg_error("missing")
            project = val
            seen_project = True
            i += 1
            continue
        return project, arg_error("unexpected", a)
    return project, None


@dataclass
class MatchSpan:
    line_no: int          # 1-based
    start: int            # character offset in line
    end: int
    text: str


@dataclass
class ResultFile:
    path: str             # relative POSIX-ish path
    abs_path: str
    count: int
    matches: List[MatchSpan] = field(default_factory=list)
    lines: List[str] = field(default_factory=list)


class Matcher:
    def __init__(self, query: str, mode: int):
        self.query = query
        self.mode = mode
        self._regex: Optional[re.Pattern[str]] = None
        if query and mode == 4:
            try:
                self._regex = re.compile(query)
            except re.error:
                self._regex = None
        elif query and mode in (2, 3):
            flags = 0 if mode == 3 else re.IGNORECASE
            try:
                self._regex = re.compile(r"(?<!\w)" + re.escape(query) + r"(?!\w)", flags)
            except re.error:
                self._regex = None

    def spans_in_line(self, line: str) -> List[Tuple[int, int, str]]:
        q = self.query
        if not q:
            return []
        if self.mode == 4:
            if self._regex is None:
                return []
            out = []
            try:
                for m in self._regex.finditer(line):
                    if m.start() == m.end():
                        continue
                    out.append((m.start(), m.end(), m.group(0)))
            except Exception:
                return []
            return out
        if self.mode in (2, 3):
            if self._regex is None:
                return []
            return [(m.start(), m.end(), m.group(0)) for m in self._regex.finditer(line)]
        case_sensitive = self.mode == 1
        hay = line if case_sensitive else line.casefold()
        needle = q if case_sensitive else q.casefold()
        out: List[Tuple[int, int, str]] = []
        pos = 0
        # Python character indexes are acceptable for the UTF-8 terminal display
        # cases used by this tool; non-overlapping matches mirror the original.
        while True:
            idx = hay.find(needle, pos)
            if idx < 0:
                break
            end = idx + len(q)
            out.append((idx, end, line[idx:end]))
            pos = end if end > idx else idx + 1
        return out

    def has_match(self, line: str) -> bool:
        return bool(self.spans_in_line(line))


class Replacer:
    def __init__(self, query: str, search_mode: int, repl: str, repl_mode: int):
        # The observed executable performs regex-mode writes using the simple
        # literal engine; a metacharacter pattern therefore finds results but does
        # not change files unless the literal text exists.
        self.query = query
        self.search_mode = 0 if search_mode == 4 else search_mode
        self.repl = repl
        self.repl_mode = repl_mode
        self.matcher = Matcher(query, self.search_mode)
        self._rx: Optional[re.Pattern[str]] = None
        if self.search_mode in (2, 3):
            flags = 0 if self.search_mode == 3 else re.IGNORECASE
            self._rx = re.compile(r"(?<!\w)" + re.escape(query) + r"(?!\w)", flags)

    def preserve(self, matched: str) -> str:
        r = self.repl
        if matched.isupper():
            return r.upper()
        if matched[:1].isupper():
            return r[:1].upper() + r[1:].lower()
        return r.lower()

    def replace_text(self, text: str) -> str:
        if not self.query:
            return text
        if self.repl_mode == 2:
            # Delete every line that contains a match, then join without a final
            # newline (as observed).
            lines = text.splitlines()
            kept = [ln for ln in lines if not self.matcher.has_match(ln)]
            return "\n".join(kept)
        if self.search_mode in (2, 3):
            rx = self._rx
            if rx is None:
                return text
            def subfn(m: re.Match[str]) -> str:
                return self.preserve(m.group(0)) if self.repl_mode == 1 else self.repl
            return rx.sub(subfn, text)
        # Simple substring replacement with optional case-insensitivity.
        case_sensitive = self.search_mode == 1
        hay = text if case_sensitive else text.casefold()
        needle = self.query if case_sensitive else self.query.casefold()
        out: List[str] = []
        pos = 0
        n = len(self.query)
        while True:
            idx = hay.find(needle, pos)
            if idx < 0:
                out.append(text[pos:])
                break
            out.append(text[pos:idx])
            matched = text[idx:idx + n]
            out.append(self.preserve(matched) if self.repl_mode == 1 else self.repl)
            pos = idx + n
        return "".join(out)


class SerplTUI:
    def __init__(self, project_root: str):
        self.root = os.path.abspath(project_root)
        self.search_text = ""
        self.replace_text = ""
        self.search_mode = 0
        self.replace_mode = 0
        self.focus = 0  # 0 search, 1 replace, 2 result list
        self.results: List[ResultFile] = []
        self.selected = -1
        self.scroll = 0
        self.running = True
        self.help_open = False
        self.help_tab = 0
        self.confirm_open = False
        self.confirm_continue = False  # default Cancel
        self.confirm_scope: str = "all"  # all or selected
        self.old_term: Optional[List] = None
        self.last_size = (0, 0)

    # ---------- terminal management ----------
    def start(self) -> None:
        self.old_term = termios.tcgetattr(sys.stdin.fileno())
        tty.setraw(sys.stdin.fileno())
        sys.stdout.write("\x1b[?1049h\x1b[?25l")
        sys.stdout.flush()

    def stop(self) -> None:
        try:
            if self.old_term is not None:
                termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, self.old_term)
        finally:
            sys.stdout.write(RESET + "\x1b[?1049l\x1b[?25h")
            sys.stdout.flush()

    def run(self) -> int:
        self.start()
        try:
            self.draw()
            while self.running:
                r, _, _ = select.select([sys.stdin], [], [], 0.20)
                if r:
                    data = os.read(sys.stdin.fileno(), 64)
                    if not data:
                        break
                    for key in self.decode_keys(data):
                        self.handle_key(key)
                        if not self.running:
                            break
                    self.draw()
                else:
                    size = shutil.get_terminal_size((80, 24))
                    if (size.columns, size.lines) != self.last_size:
                        self.draw()
            return 0
        finally:
            self.stop()

    def decode_keys(self, data: bytes) -> List[str]:
        keys: List[str] = []
        i = 0
        while i < len(data):
            b = data[i]
            if b == 0x1b:
                # Common CSI keys.
                if data[i:i+3] == b"\x1b[A":
                    keys.append("UP"); i += 3; continue
                if data[i:i+3] == b"\x1b[B":
                    keys.append("DOWN"); i += 3; continue
                if data[i:i+3] == b"\x1b[C":
                    keys.append("RIGHT"); i += 3; continue
                if data[i:i+3] == b"\x1b[D":
                    keys.append("LEFT"); i += 3; continue
                if data[i:i+3] == b"\x1b[Z":
                    keys.append("BTAB"); i += 3; continue
                keys.append("ESC")
                i += 1
                continue
            if b in (10, 13):
                keys.append("ENTER")
            elif b == 9:
                keys.append("TAB")
            elif b == 127 or b == 8:
                keys.append("BACKSPACE")
            elif b == 3:
                keys.append("C-c")
            elif b == 4:
                keys.append("C-d")
            elif b == 18:
                keys.append("C-r")
            elif b == 26:
                keys.append("C-z")
            elif b == 15:
                keys.append("C-o")
            elif b == 2:
                keys.append("C-b")
            elif b == 14:
                keys.append("C-n")
            elif 32 <= b < 127:
                keys.append(chr(b))
            # UTF-8 printable bytes: try decoding a full character.
            elif b >= 128:
                for j in range(1, 5):
                    try:
                        ch = data[i:i+j].decode("utf-8")
                        keys.append(ch)
                        i += j - 1
                        break
                    except Exception:
                        pass
            i += 1
        return keys

    # ---------- filesystem/search ----------
    def iter_files(self) -> List[str]:
        out: List[str] = []
        if not os.path.isdir(self.root):
            return out
        for dirpath, dirnames, filenames in os.walk(self.root, topdown=True, followlinks=False):
            # Skip hidden directories and symlinks.  Order is intentionally not
            # over-engineered; the original uses a non-stable collection/order.
            dirnames[:] = [d for d in dirnames if not d.startswith('.') and not os.path.islink(os.path.join(dirpath, d))]
            for fn in filenames:
                if fn.startswith('.'):
                    continue
                ap = os.path.join(dirpath, fn)
                if os.path.islink(ap) or not os.path.isfile(ap):
                    continue
                out.append(ap)
        # A stable but reverse-biased order gives similar small examples while
        # avoiding process-random hash ordering.
        return sorted(out, key=lambda p: os.path.relpath(p, self.root))

    def read_text_file(self, ap: str) -> Optional[str]:
        try:
            data = Path(ap).read_bytes()
        except Exception:
            return None
        if b"\x00" in data:
            return None
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError:
            return None

    def do_search(self) -> None:
        self.results = []
        self.selected = -1
        self.scroll = 0
        if not self.search_text:
            return
        matcher = Matcher(self.search_text, self.search_mode)
        # Invalid regex yields no results.
        if self.search_mode == 4 and matcher._regex is None:
            return
        for ap in self.iter_files():
            text = self.read_text_file(ap)
            if text is None:
                continue
            lines = text.splitlines()
            matches: List[MatchSpan] = []
            for lno, line in enumerate(lines, 1):
                for s, e, mt in matcher.spans_in_line(line):
                    matches.append(MatchSpan(lno, s, e, mt))
            if matches:
                rel = os.path.relpath(ap, self.root).replace(os.sep, "/")
                self.results.append(ResultFile(rel, ap, len(matches), matches, lines))

    def apply_replace_to_file(self, rf: ResultFile) -> None:
        text = self.read_text_file(rf.abs_path)
        if text is None:
            return
        new = Replacer(self.search_text, self.search_mode, self.replace_text, self.replace_mode).replace_text(text)
        try:
            Path(rf.abs_path).write_text(new, encoding="utf-8")
        except Exception:
            pass

    def confirm_replace(self) -> None:
        if self.confirm_scope == "selected":
            if 0 <= self.selected < len(self.results):
                rf = self.results[self.selected]
                self.apply_replace_to_file(rf)
                del self.results[self.selected]
                if self.selected >= len(self.results):
                    self.selected = len(self.results) - 1
                if not self.results:
                    self.selected = -1
            self.confirm_open = False
            self.confirm_continue = False
            return
        # Replace all pending result files, then reset to the initial UI state.
        for rf in list(self.results):
            self.apply_replace_to_file(rf)
        self.search_text = ""
        self.replace_text = ""
        self.search_mode = 0
        self.replace_mode = 0
        self.results = []
        self.selected = -1
        self.scroll = 0
        self.focus = 0
        self.confirm_open = False
        self.confirm_continue = False

    # ---------- input handling ----------
    def handle_key(self, key: str) -> None:
        if key in ("C-c", "C-d"):
            self.running = False
            return
        if key == "C-z":
            # Restore the terminal while suspended, then redraw on resume.
            if self.old_term is not None:
                termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, self.old_term)
            sys.stdout.write(RESET + "\x1b[?25h")
            sys.stdout.flush()
            os.kill(os.getpid(), signal.SIGTSTP)
            tty.setraw(sys.stdin.fileno())
            sys.stdout.write("\x1b[?25l")
            sys.stdout.flush()
            return
        if self.help_open:
            if key in ("ESC", "q"):
                self.help_open = False
            elif key == "RIGHT":
                self.help_tab = min(1, self.help_tab + 1)
            elif key == "LEFT":
                self.help_tab = max(0, self.help_tab - 1)
            elif key == "TAB":
                self.help_tab = 1 - self.help_tab
            return
        if self.confirm_open:
            if key == "ESC":
                self.confirm_open = False
                self.confirm_continue = False
            elif key in ("LEFT", "h"):
                self.confirm_continue = True
            elif key in ("RIGHT", "l", "TAB"):
                self.confirm_continue = False
            elif key == "ENTER":
                if self.confirm_continue:
                    self.confirm_replace()
                else:
                    self.confirm_open = False
                    self.confirm_continue = False
            return
        if key == "C-b":
            self.help_open = True
            self.help_tab = 0
            return
        if key == "TAB":
            self.focus = (self.focus + 1) % 3
            return
        if key == "BTAB":
            self.focus = (self.focus - 1) % 3
            return
        if key == "C-r":
            self.do_search()
            return
        if key == "C-o":
            if self.results and self.search_text:
                self.confirm_open = True
                self.confirm_continue = False
                self.confirm_scope = "all"
            return
        if self.focus == 0:
            self.handle_search_key(key)
        elif self.focus == 1:
            self.handle_replace_key(key)
        else:
            self.handle_results_key(key)

    def handle_search_key(self, key: str) -> None:
        if key == "ENTER":
            self.do_search()
        elif key == "BACKSPACE":
            self.search_text = self.search_text[:-1]
        elif key == "C-n":
            self.search_mode = (self.search_mode + 1) % len(SEARCH_MODES)
        elif len(key) == 1 and key >= " ":
            self.search_text += key

    def handle_replace_key(self, key: str) -> None:
        if key == "BACKSPACE":
            self.replace_text = self.replace_text[:-1]
        elif key == "C-n":
            self.replace_mode = (self.replace_mode + 1) % len(REPLACE_MODES)
        elif len(key) == 1 and key >= " ":
            self.replace_text += key

    def handle_results_key(self, key: str) -> None:
        if not self.results:
            return
        if self.selected < 0:
            if key in ("DOWN", "UP", "j", "k", "g", "G", "h", "l", "LEFT", "RIGHT"):
                self.selected = 0
        if key in ("DOWN", "j"):
            self.selected = min(len(self.results) - 1, self.selected + (0 if self.selected < 0 else 1))
        elif key in ("UP", "k"):
            if self.selected < 0:
                self.selected = 0
            else:
                self.selected = max(0, self.selected - 1)
        elif key in ("g", "h", "LEFT"):
            self.selected = 0
        elif key in ("G", "l", "RIGHT"):
            self.selected = len(self.results) - 1
        elif key == "d":
            if 0 <= self.selected < len(self.results):
                del self.results[self.selected]
                if self.selected >= len(self.results):
                    self.selected = len(self.results) - 1
                if not self.results:
                    self.selected = -1
        elif key == "r":
            if 0 <= self.selected < len(self.results):
                self.confirm_open = True
                self.confirm_continue = False
                self.confirm_scope = "selected"
        elif key == "ENTER":
            # The original advertises opening a file.  In this dependency-free
            # implementation Enter is a harmless no-op inside the list.
            pass
        # Keep selection visible.
        visible = max(1, self.result_height() - 2)
        if self.selected < self.scroll:
            self.scroll = self.selected
        elif self.selected >= self.scroll + visible:
            self.scroll = self.selected - visible + 1

    # ---------- drawing ----------
    def term_size(self) -> Tuple[int, int]:
        s = shutil.get_terminal_size((80, 24))
        w = max(20, s.columns)
        h = max(10, s.lines)
        self.last_size = (w, h)
        return w, h

    def left_width(self, w: int) -> int:
        return max(20, min(45, int(w * 0.30)))

    def result_height(self) -> int:
        w, h = self.term_size()
        return max(3, h - 7)

    def fit(self, s: str, width: int) -> str:
        # ANSI-free fit; crop by codepoints and pad with spaces.
        if len(s) > width:
            return s[:width]
        return s + " " * (width - len(s))

    def top_border(self, width: int, title: str, suffix: Optional[str] = None) -> str:
        inner = width - 2
        if suffix:
            label = title
            suff = f"[{suffix}]"
            dashes = max(0, inner - len(label) - len(suff))
            return "╭" + label + "─" * dashes + suff + "╮"
        label = title
        return "╭" + label + "─" * max(0, inner - len(label)) + "╮"

    def bottom_border(self, width: int) -> str:
        return "╰" + "─" * (width - 2) + "╯"

    def content_line(self, width: int, text: str = "", selected: bool = False) -> str:
        inner = self.fit(text, width - 2)
        if selected:
            return "│" + BG_BLUE + inner + RESET + "│"
        return "│" + inner + "│"

    def draw(self) -> None:
        w, h = self.term_size()
        lw = self.left_width(w)
        rw = max(1, w - lw)
        body_h = h - 1
        rows: List[str] = []
        preview = self.preview_lines(rw - 2, body_h - 2)
        # Build left panes and right pane side by side.
        for y in range(body_h):
            left = self.left_at_row(y, lw)
            right = self.right_at_row(y, rw, preview)
            rows.append(left + right)
        footer = self.footer_text()
        rows.append(self.fit(footer, w))
        sys.stdout.write("\x1b[H" + RESET + "\n".join(rows))
        if self.confirm_open:
            self.draw_confirm(w, h)
        if self.help_open:
            self.draw_help(w, h)
        sys.stdout.flush()

    def left_at_row(self, y: int, lw: int) -> str:
        # Search: rows 0..2; Replace: 3..5; Results: 6..body-1.
        if y == 0:
            return self.top_border(lw, "Search", SEARCH_MODES[self.search_mode])
        if y == 1:
            return self.content_line(lw, self.search_text[:max(0, lw - 2)])
        if y == 2:
            return self.bottom_border(lw)
        if y == 3:
            return self.top_border(lw, "Replace", REPLACE_MODES[self.replace_mode])
        if y == 4:
            return self.content_line(lw, self.replace_text[:max(0, lw - 2)])
        if y == 5:
            return self.bottom_border(lw)
        if y == 6:
            return self.top_border(lw, "Result List")
        body_h = self.term_size()[1] - 1
        if y == body_h - 1:
            return self.bottom_border(lw)
        idx = self.scroll + (y - 7)
        if 0 <= idx < len(self.results):
            rf = self.results[idx]
            text = f"{rf.path} ({rf.count})"
            sel = (idx == self.selected and self.focus == 2)
            return self.content_line(lw, text, sel)
        return self.content_line(lw, "")

    def right_at_row(self, y: int, rw: int, preview: List[str]) -> str:
        inner_w = rw - 2
        body_h = self.term_size()[1] - 1
        if y == 0:
            return self.top_border(rw, "Preview")
        if y == body_h - 1:
            return self.bottom_border(rw)
        txt = preview[y - 1] if 0 <= y - 1 < len(preview) else ""
        return self.content_line(rw, txt[:inner_w])

    def preview_lines(self, width: int, max_lines: int) -> List[str]:
        if not (0 <= self.selected < len(self.results)):
            return []
        rf = self.results[self.selected]
        out: List[str] = []
        sep = "-" * width
        for m in rf.matches:
            start = max(1, m.line_no - 1)
            end = min(len(rf.lines), m.line_no + 1)
            for lno in range(start, end + 1):
                if 1 <= lno <= len(rf.lines):
                    out.append(f"{lno:4d} {rf.lines[lno-1]}")
                    if len(out) >= max_lines:
                        return out
            out.append(sep)
            if len(out) >= max_lines:
                return out
        return out

    def footer_text(self) -> str:
        if self.help_open:
            return "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
        if self.confirm_open:
            return "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>"
        if self.focus == 0:
            return "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
        if self.focus == 1:
            return "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
        return "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"

    def overlay_put(self, x: int, y: int, text: str) -> None:
        sys.stdout.write(f"\x1b[{y};{x}H{text}")

    def draw_confirm(self, w: int, h: int) -> None:
        box_w = 56
        lines = [
            "╭" + "─" * 20 + "Confirm Dialog" + "─" * 20 + "╮",
            "│" + " " * 54 + "│",
            "│ This action will modify the files in this directory. │",
            "│          Are you sure you want to continue?          │",
            "│" + " " * 54 + "│",
            "│" + " " * 54 + "│",
            "│" + " " * 19 + "Continue  Cancel" + " " * 19 + "│",
            "╰" + "─" * 54 + "╯",
        ]
        if self.confirm_continue:
