        else:
            lines[6] = "│" + " " * 19 + "Continue  " + BOLD + FG_YELLOW + "Cancel" + RESET + " " * 19 + "│"
        x = max(1, (w - box_w) // 2 + 1)
        y = max(1, (h - len(lines)) // 2 + 1)
        for i, line in enumerate(lines):
            self.overlay_put(x, y + i, line)

    def draw_help(self, w: int, h: int) -> None:
        box_w = min(80, max(40, w - 20))
        inner = box_w - 2
        box_h = 16
        x = max(1, (w - box_w) // 2 + 1)
        y = max(1, (h - box_h) // 2 + 1)
        title = " [1] Global ─ [2] Navigation "
        close = "Press 'q' to close"
        top_mid = title + "─" * max(0, inner - len(title) - len(close)) + close
        lines = ["╭" + self.fit(top_mid, inner) + "╮"]
        if self.help_tab == 0:
            content = [
                "",
                " - Ctrl-c: Quit",
                " - Ctrl-d: Quit",
                " - Ctrl-b: Help dialog",
                " - Ctrl-o: Process Replace For All Files",
                " - Ctrl-n: Loop through search and replace modes",
                " - Enter: Select/Deselect file",
                " - d: delete file/delete line from the replace process",
                " - r: Replace Selected File Or Line",
            ]
        else:
            content = [
                "",
                " - Tab: Loop through panes",
                " - j/UpArrow: Move up",
                " - k/DownArrow: Move down",
                " - h/g/LeftArrow: Move to Top",
                " - l/G/RightArrow: Move to Bottom",
            ]
        for i in range(box_h - 2):
            text = content[i] if i < len(content) else ""
            lines.append("│" + self.fit(text, inner) + "│")
        lines.append("╰" + "─" * inner + "╯")
        for i, line in enumerate(lines):
            self.overlay_put(x, y + i, line)


def non_tty_error() -> int:
    eprint("serpl error: Something went wrong\n"
           "Error: \n"
           "   0: \x1b[91mResource temporarily unavailable (os error 11)\x1b[0m\n")
    return 1


def main(argv: List[str]) -> int:
    project, handled = parse_args(argv)
    if handled is not None:
        return handled
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        return non_tty_error()
    app = SerplTUI(project or ".")
    try:
        return app.run()
    except OSError as exc:
        eprint("serpl error: Something went wrong\n"
               "Error: \n"
               f"   0: \x1b[91m{exc}\x1b[0m\n")
        return 1
    except KeyboardInterrupt:
        return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
